"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[22874],{22874:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/beaef098bba51fc1510e7076ff8cb8eb.jpg\\"\\n  title=\\"Stitch Coffee QVB\\"\\n  cuisine=\\"카페\\"\\n  address=\\"Ground Level QVB, Shop G054/455 George St, Sydney NSW 2000 오스트레일리아\\"\\n  rating=3\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\n<mark>퀸 빅토리아 빌딩(QVB)</mark> 안에 위치한 커피숍이다.\\n\\n대표 메뉴인 <mark>화이트 레빗</mark> 라떼와 롱블랙을 주문했다.  \\n오렌지 제스트가 올려져 있고, 전체적으로 깔끔한 라떼 느낌이었다.  \\n특별히 뛰어난 맛인지는 솔직히 모르겠다.\\n\\n하지만 시드니를 방문한다면 QVB는 한번쯤 들르게 되는 곳이고,  \\n그때 커피 한 잔 마시며 쉬어가기에는 나쁘지 않은 선택이다.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/beaef098bba51fc1510e7076ff8cb8eb.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Stitch Coffee QVB\\">\\n<img src=\\"/assets/snippets/location/bd460f8720474e61e1b06ad905c234a8.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Stitch Coffee QVB\\">\\n</pictures>\\n"}')}}]);